-- The schema the entities define, generated by Hibernate (PostgreSQLDialect). Runs on PostgreSQL and
-- on H2 in MODE=PostgreSQL. A database that predates Flyway is baselined at 1 and never runs it.
-- Enum columns are plain varchar without a CHECK of their constants, so a new RunStatus or Role
-- needs no migration.

create table application_user (
    version integer not null,
    id bigint generated by default as identity,
    hashed_password varchar(255),
    name varchar(255),
    username varchar(255),
    primary key (id)
);

create table customer (
    version integer not null,
    id bigint generated by default as identity,
    code varchar(255),
    country varchar(255),
    email varchar(255),
    firstname varchar(255),
    lastname varchar(255),
    location varchar(255),
    organization varchar(255),
    street varchar(255),
    primary key (id)
);

create table file_metadata (
    version integer not null,
    id bigint generated by default as identity,
    test_result_id bigint,
    file_name varchar(255) not null,
    file_path varchar(255),
    primary key (id)
);

create table gear_standard (
    version integer not null,
    id bigint generated by default as identity,
    description text,
    name varchar(255),
    primary key (id)
);

create table gear_type (
    version integer not null,
    id bigint generated by default as identity,
    name varchar(255),
    primary key (id)
);

create table material (
    version integer not null,
    id bigint generated by default as identity,
    description text,
    name varchar(255),
    primary key (id)
);

create table project (
    version integer not null,
    customer_id bigint not null,
    id bigint generated by default as identity,
    owner_id bigint,
    description text,
    name varchar(255) not null,
    primary key (id)
);

create table sample (
    version integer not null,
    year_of_manufacture integer not null check ((year_of_manufacture >= 1900) and (year_of_manufacture <= 2900)),
    id bigint generated by default as identity,
    owner_id bigint,
    project_id bigint not null,
    description text,
    manufacturer varchar(255),
    model varchar(255),
    name varchar(255),
    primary key (id)
);

create table sample_gear_standard (
    gear_standards_id bigint not null,
    sample_id bigint not null
);

create table sample_gear_type (
    gear_types_id bigint not null,
    sample_id bigint not null
);

create table sample_material (
    materials_id bigint not null,
    sample_id bigint not null
);

create table test_parameter (
    cycle_count integer,
    lower_shut_off_threshold float(53),
    lower_turn_force float(53),
    speed integer not null,
    start_ramp_seconds float(53),
    stop_ramp_seconds float(53),
    upper_shut_off_threshold float(53),
    upper_turn_force float(53),
    version integer not null,
    id bigint generated by default as identity,
    owner_id bigint,
    type varchar(255),
    primary key (id)
);

create table test_result (
    version integer not null,
    id bigint generated by default as identity,
    owner_id bigint,
    sample_id bigint not null,
    test_parameter_id bigint not null,
    run_status varchar(32),
    description text,
    interruption_log text,
    result_text text,
    primary key (id)
);

create table user_roles (
    user_id bigint not null,
    roles varchar(255),
    constraint UKsrkqdub13dwp1aulg8si368lb unique (user_id, roles)
);

